"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[454],{47767:e=>{e.exports=JSON.parse('{"functions":[{"name":"doCleanup","desc":"Cleans up every task passed as an argument. A task can be any of:\\n\\n- an `Instance` - will be destroyed\\n- an `RBXScriptConnection` - will be disconnected\\n- a function - will be run\\n- a table with a `destroy` or `Destroy` method - will be called\\n- an array - each item is cleaned up in reverse order, so tasks run\\n  opposite to their construction order, then removed from the array\\n\\nUnrecognised values are ignored.","params":[{"name":"...","desc":"Tasks to clean up.","lua_type":"unknown"}],"returns":[],"function_type":"static","source":{"line":30,"path":"plugin/do-cleanup/init.luau"}}],"properties":[],"types":[],"name":"doCleanup","desc":"Cleans up the tasks passed in as the arguments, in the style of Fusion\'s\\nscopes: collect connections, instances and callbacks into an array as you\\ncreate them, then hand the array to `doCleanup` when tearing down.","source":{"line":12,"path":"plugin/do-cleanup/init.luau"}}')}}]);